import requests
import uuid
from os import getenv

from taf.gnb.oam.coam.cu.utilities.base64 import base64ify
from taf.gnb.oam.coam.cu.utilities.token_storage import TokenStorage
from taf.gnb.oam.coam.cu.utilities.logger import (
    log_sending_message,
    log_received_response,
    log_debug
)


def update_expired_password(connection_details, new_password="Nokia@123"):
    """
    Responsible for updating expired password in case of failed log in attempt
    """
    disable_logging = getenv("TAF_VDU_CLIENT_DISABLE_LOGGING", "False").lower() == "true"
    request_id = str(uuid.uuid4())
    access_token = TokenStorage(connection_name=connection_details.alias).access_token
    url = connection_details.make_configuration_host(
        original_endpoint="http://localhost/api/asm/v1/account/expired-password"
    )
    headers = {
        "X-Nokia-Username": "Nemuadmin",
        "X-Nokia-Accessmode": "rw",
        "Authorization": f"Bearer {access_token}",
        "accept": "application/json",
        "Content-Type": "application/json"
    }

    password_info = {
        "username": base64ify(connection_details.username),
        "password": base64ify(connection_details.password),
        "newPassword": base64ify(new_password)
    }

    if not disable_logging:
        log_sending_message(
            request_id=request_id,
            endpoint=url,
            headers=headers,
            method="PATCH",
            connection_alias=connection_details.alias,
            json=password_info
        )

        log_debug(
            f"Password you gave: {connection_details.password} expired, "
            f"trying to update it to Nokia@123 and log in using new password."
        )

    response = requests.patch(url=url, json=password_info, headers=headers, verify=False)

    if not disable_logging:
        log_received_response(
            request_id=request_id,
            response=response,
            endpoint=url,
            method="PATCH",
            connection_alias=connection_details.alias
        )

    response.raise_for_status()
